1	// Fresh isolated browser capture. No production/profile-wide browser configuration.
2	import { spawn } from 'node:child_process';
3	import { access, mkdir, readFile, writeFile, mkdtemp, realpath, rm } from 'node:fs/promises';
4	import { resolve, join, relative, sep } from 'node:path';
5	import { tmpdir } from 'node:os';
6	import { serve, rendererRoot, hash } from './server.mjs';
7	
8	const option = name => { const i = process.argv.indexOf(name); return i < 0 ? null : process.argv[i + 1]; };
9	const project = resolve(option('--project') || join(rendererRoot, '..'));
10	const output = option('--out');
11	if (!output) throw new Error('Use --out NEW_DIRECTORY to retain a fresh capture');
12	const out = resolve(output);
13	await mkdir(out, { recursive: false });
14	let browser = option('--browser');
15	if (!browser) {
16	  for (const file of [join(process.env.PROGRAMFILES || '', 'Google/Chrome/Application/chrome.exe'), join(process.env['ProgramFiles(x86)'] || '', 'Microsoft/Edge/Application/msedge.exe')]) {
17	    try { await access(file); browser = file; break; } catch { /* Try next installed browser. */ }
18	  }
19	}
20	if (!browser) throw new Error('No local Chromium browser found; pass --browser PATH');
21	const profileParent = await realpath(tmpdir());
22	const profile = await mkdtemp(join(profileParent, 'pixl-render-'));
23	const rendererFiles = Object.fromEntries(await Promise.all(['server.mjs', 'capture.mjs', 'index.html', 'view.mjs', 'check.py'].map(async name => [name, hash(await readFile(join(rendererRoot, name)))])));
24	let observed, child, socket;
25	let stdout = '', stderr = '', exitCode = null, launchError = null;
26	const commands = [];
27	const pending = new Map();
28	const deadline = Date.now() + 45_000;
29	const pause = () => new Promise(yes => setTimeout(yes, 25));
30	const running = await serve(project, report => { if (observed) throw new Error('Duplicate capture'); observed = report; });
31	// Do not mix --screenshot's late viewport resize with earlier page measurements.
32	// One CDP page sets device metrics before navigation and captures both artifacts.
33	const args = ['--headless=new', '--disable-gpu', '--hide-scrollbars', '--no-first-run', '--no-default-browser-check', '--disable-background-networking', `--user-data-dir=${profile}`, '--remote-debugging-address=127.0.0.1', '--remote-debugging-port=0', 'about:blank'];
34	const viewport = { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false };
35	await writeFile(join(out, 'launch.json'), JSON.stringify({ browser, args, project, node: process.version, viewport, scope: 'Isolated local fixture renderer; one CDP page, metrics set before navigation' }, null, 2) + '\n');
36	
37	async function waitFor(check) {
38	  while (true) {
39	    const value = await check();
40	    if (value) return value;
41	    if (launchError) throw launchError;
42	    if (exitCode !== null) throw new Error(`Browser exited before capture: ${exitCode}`);
43	    if (Date.now() >= deadline) throw new Error('Browser capture exceeded 45 seconds');
44	    await pause();
45	  }
46	}
47	
48	let commandId = 0;
49	function call(method, params = {}, sessionId) {
50	  const id = ++commandId;
51	  commands.push({ id, method, params, ...(sessionId ? { sessionId } : {}) });
52	  return new Promise((yes, no) => {
53	    const timer = setTimeout(() => { pending.delete(id); no(new Error(`CDP timeout: ${method}`)); }, Math.max(1, deadline - Date.now()));
54	    pending.set(id, { yes: value => { clearTimeout(timer); yes(value); }, no: error => { clearTimeout(timer); no(error); } });
55	    socket.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
56	  });
57	}
58	
59	try {
60	  child = spawn(browser, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
61	  child.stdout.on('data', chunk => { stdout += chunk; }); child.stderr.on('data', chunk => { stderr += chunk; });
62	  child.once('error', error => { launchError = error; });
63	  child.once('exit', code => { exitCode = code ?? -1; });
64	  const endpoint = await waitFor(() => stderr.match(/DevTools listening on (ws:\/\/127\.0\.0\.1:\d+\/devtools\/browser\/[^\s]+)/)?.[1]);
65	  socket = new WebSocket(endpoint);
66	  await new Promise((yes, no) => { socket.addEventListener('open', yes, { once: true }); socket.addEventListener('error', no, { once: true }); });
67	  socket.addEventListener('message', event => {
68	    const message = JSON.parse(event.data);
69	    const item = pending.get(message.id);
70	    if (!item) return;
71	    pending.delete(message.id);
72	    if (message.error) item.no(new Error(JSON.stringify(message.error))); else item.yes(message.result);
73	  });
74	  const version = await call('Browser.getVersion');
75	  const { targetId } = await call('Target.createTarget', { url: 'about:blank' });
76	  const { sessionId } = await call('Target.attachToTarget', { targetId, flatten: true });
77	  await call('Page.enable', {}, sessionId);
78	  await call('Emulation.setDeviceMetricsOverride', viewport, sessionId);
79	  await call('Page.navigate', { url: `${running.url}/?capture=1` }, sessionId);
80	  await waitFor(() => observed);
81	  await waitFor(async () => (await call('Runtime.evaluate', { expression: 'document.body.dataset.captureComplete === "true"', returnByValue: true }, sessionId)).result.value);
82	  await call('Runtime.evaluate', { expression: 'new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve(true))))', awaitPromise: true, returnByValue: true }, sessionId);
83	  const layout = await call('Page.getLayoutMetrics', {}, sessionId);
84	  const result = await call('Page.captureScreenshot', { format: 'png', fromSurface: true, captureBeyondViewport: false }, sessionId);
85	  const screenshot = Buffer.from(result.data, 'base64');
86	  await writeFile(join(out, 'destination.png'), screenshot);
87	  observed.browser_version = version;
88	  observed.capture_layout = layout;
89	  observed.capture_method = 'CDP metrics before navigation, page report, layout, screenshot in the same page session';
90	  let index = 0;
91	  for (const item of [...observed.views, ...observed.timeline, ...(observed.playback?.samples ?? []).flatMap(sample => sample.cells)]) if (item.png) {
92	    const bytes = Buffer.from(item.png.split(',')[1], 'base64');
93	    const name = `view-${String(index++).padStart(3, '0')}.png`;
94	    await writeFile(join(out, name), bytes); item.image = { path: name, sha256: hash(bytes) }; delete item.png;
95	  }
96	  observed.served_files = Object.fromEntries(running.served);
97	  for (const [name, expected] of Object.entries(rendererFiles)) if (hash(await readFile(join(rendererRoot, name))) !== expected) throw new Error(`Renderer changed during capture: ${name}`);
98	  observed.renderer_files = rendererFiles;
99	  observed.screenshot = { path: 'destination.png', sha256: hash(screenshot) };
100	  observed.observed_at = new Date().toISOString();
101	  await writeFile(join(out, 'render.json'), JSON.stringify(observed, null, 2) + '\n');
102	  console.log(JSON.stringify({ capture: join(out, 'render.json'), screenshot: join(out, 'destination.png'), missing: observed.missing, errors: observed.errors }));
103	} finally {
104	  if (socket?.readyState === WebSocket.OPEN) {
105	    try { await call('Browser.close'); } catch { /* Process may already have exited. */ }
106	    socket.close();
107	  }
108	  for (const item of pending.values()) item.no(new Error('Capture closed'));
109	  pending.clear();
110	  if (child && exitCode === null) {
111	    const until = Date.now() + 2000;
112	    while (exitCode === null && Date.now() < until) await pause();
113	    if (exitCode === null) child.kill();
114	  }
115	  await writeFile(join(out, 'browser-process.json'), JSON.stringify({ code: exitCode, stdout, stderr, error: launchError ? String(launchError) : null }, null, 2) + '\n');
