1	import { stateAfter } from '/src/queue.ts';
2	import { statusVisuals, statusCell, compactStatus, display } from '/src/queue-view.ts';
3	
4	const panel = display.background;
5	document.documentElement.style.setProperty('--panel', panel);
6	const cache = new Map();
7	const cells = [];
8	const consumers = { statusCell, compactStatus };
9	const events = ['idle', 'started', 'pause', 'ok', 'error'].filter(event => event === 'idle' || statusVisuals[stateAfter(event)]);
10	document.querySelectorAll('[data-event]').forEach(button => { button.hidden = !events.includes(button.dataset.event); });
11	const errors = [];
12	window.addEventListener('error', event => errors.push(event.message));
13	window.addEventListener('unhandledrejection', event => errors.push(String(event.reason)));
14	const digest = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');
15	
16	async function imageFor(path) {
17	  if (!cache.has(path)) cache.set(path, (async () => {
18	    const response = await fetch(`/${path}`);
19	    if (!response.ok) return { available: false, status: response.status, path };
20	    const data = await response.arrayBuffer();
21	    const image = new Image();
22	    const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
23	    try { image.src = url; await image.decode(); }
24	    finally { URL.revokeObjectURL(url); }
25	    return { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
26	  })());
27	  return cache.get(path);
28	}
29	
30	function paint(canvas, asset, frames, scale, elapsed) {
31	  const [width, height] = display.cell;
32	  const frame = Math.floor(Math.max(elapsed, 0) / display.frameMs) % frames;
33	  const context = canvas.getContext('2d', { willReadFrequently: true });
34	  context.imageSmoothingEnabled = display.filter !== 'nearest';
35	  context.fillStyle = panel;
36	  context.fillRect(0, 0, canvas.width, canvas.height);
37	  if (asset.available && asset.width === width * frames && asset.height === height) {
38	    context.drawImage(asset.image, frame * width, 0, width, height, 0, 0, width * scale, height * scale);
39	  }
40	  return frame;
41	}
42	
43	async function makeCell(consumer, state, scale, elapsed = 0, track = true) {
44	  const descriptor = consumers[consumer](state);
45	  const asset = await imageFor(descriptor.path);
46	  const node = document.createElement('div');
47	  node.className = `cell ${consumer === 'compactStatus' ? 'compact' : ''}`;
48	  const glyph = document.createElement('span'); glyph.className = 'glyph';
49	  const label = document.createElement('span'); label.textContent = descriptor.label;
50	  node.append(glyph, label);
51	  const info = { consumer, state, scale, descriptor, asset: { ...asset, image: undefined }, node, canvas: null, frame: 0 };
52	  if (asset.available) {
53	    const canvas = document.createElement('canvas');
54	    canvas.width = display.cell[0] * scale; canvas.height = display.cell[1] * scale;
