56	    info.canvas = canvas; info.frame = paint(canvas, asset, descriptor.frames, scale, elapsed);
57	    info.geometryMatches = asset.width === display.cell[0] * descriptor.frames && asset.height === display.cell[1];
58	    glyph.append(canvas);
59	    if (!info.geometryMatches) { const warning = document.createElement('span'); warning.className = 'missing'; warning.textContent = 'Wrong sheet size'; node.append(warning); }
60	  } else {
61	    glyph.classList.add('missing'); glyph.textContent = 'Missing asset';
62	  }
63	  if (track) cells.push(info);
64	  return info;
65	}
66	
67	const matrix = document.querySelector('#matrix');
68	for (const text of ['State', 'Full · 1×', `Full · ${display.scale}×`, 'Compact · 1×', `Compact · ${display.scale}×`]) {
69	  const node = document.createElement('div'); node.className = 'heading'; node.textContent = text; matrix.append(node);
70	}
71	for (const state of Object.keys(statusVisuals)) {
72	  const label = document.createElement('div'); label.className = 'row-label'; label.textContent = state; matrix.append(label);
73	  for (const consumer of Object.keys(consumers)) for (const scale of [1, display.scale]) matrix.append((await makeCell(consumer, state, scale)).node);
74	}
75	const missing = [...cache.keys()].filter(path => !cells.find(cell => cell.descriptor.path === path)?.asset.available);
76	document.querySelector('#coverage').textContent = missing.length ? `${missing.length} status assets are still missing: ${missing.join(', ')}` : 'Every mapped status asset is available; visual review remains separate.';
77	
78	let livePromise;
79	let liveCells = [];
