88	  return { event, state, consumers: liveCells.map(({ consumer, descriptor, asset }) => ({ consumer, descriptor, available: asset.available, sha256: asset.sha256 })) };
89	}
90	document.querySelectorAll('[data-event]').forEach(button => button.addEventListener('click', () => { livePromise = select(button.dataset.event); }));
91	await select('ok');
92	function animate(now) {
93	  const current = liveCells;
94	  Promise.all(current.map(async cell => {
95	    if (cell.canvas && cell.descriptor.frames > 1) {
96	      const asset = await cache.get(cell.descriptor.path);
97	      cell.frame = paint(cell.canvas, asset, cell.descriptor.frames, cell.scale, now - origin);
98	    }
99	  })).then(() => { if (current === liveCells) playbackObserver?.(now, current); });
