153	    smoothing: canvas?.getContext('2d').imageSmoothingEnabled,
154	    bounds: canvas ? Object.fromEntries(['x', 'y', 'width', 'height'].map(key => [key, canvas.getBoundingClientRect()[key]])) : null,
155	    imageRendering: canvas ? getComputedStyle(canvas).imageRendering : null,
