def show(o, depth=0, maxlen=300):
    if isinstance(o, dict):
        for k,v in o.items():
            if isinstance(v,(dict,list)):
                print("  "*depth+str(k)+":"); show(v, depth+1)
            else:
                s=str(v); print("  "*depth+f"{k}: {s[:maxlen]}{'...' if len(s)>maxlen else ''}")
