from PIL import Image
import hashlib
im = Image.open("assets/working.png").convert("RGBA")
seed = Image.open("work/live-family/working-seed-download.png").convert("RGBA")
print("seed size", seed.size, "sha", hashlib.sha256(open("work/live-family/working-seed-download.png","rb").read()).hexdigest())
frames=[im.crop((i*16,0,(i+1)*16,16)) for i in range(4)]
print("frame0 == seed:", frames[0].tobytes()==seed.tobytes())
def pix(f): 
    p=f.load(); return {(x,y):p[x,y] for y in range(16) for x in range(16) if p[x,y][3]}
f0=pix(frames[0])
# try rotations about pixel centers (cx,cy) in {7,7.5,8} clockwise & ccw
import itertools
for i in (1,2,3):
    target=pix(frames[i])
    found=[]
    for cx,cy in itertools.product([7,7.5,8],[7,7.5,8]):
        for direction in ("cw","ccw"):
            out={}
            ok=True
            for (x,y),c in f0.items():
                dx,dy=x-cx,y-cy
                for _ in range(i):
                    dx,dy = (-dy,dx) if direction=="cw" else (dy,-dx)
                nx,ny=dx+cx,dy+cy
                if nx!=int(nx) or ny!=int(ny): ok=False;break
                out[(int(nx),int(ny))]=c
            if ok and out==target: found.append((cx,cy,direction))
    print(f"frame{i}: matches", found)
# print ascii of frames
for i,f in enumerate(frames):
    p=f.load(); print(f"frame {i}")
